<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Support\{Access,Amount,Audit};
use App\Services\DocumentService;
use Carbon\Carbon;
class PayrollController {
 public function index(Request $r){Access::require($r->user(),'payroll');return Access::scope(DB::table('payroll_runs'),$r->user())->orderByDesc('id')->get();}
 public function attendanceList(Request $r){Access::require($r->user(),'payroll');return Access::scope(DB::table('attendance as a')->join('employees as e','e.id','=','a.employee_id'),$r->user(),'e.branch_id')->select('a.*','e.name')->orderByDesc('a.date')->limit(500)->get();}
 public function attendance(Request $r){Access::require($r->user(),'payroll');$v=$r->validate(['employee_id'=>'required|integer|exists:employees,id','date'=>'required|date_format:Y-m-d','status'=>'required|in:present,paid_leave,unpaid_leave,holiday,absent','overtime_minutes'=>'required|integer|min:0|max:1440','note'=>'nullable|string|max:1000']);$e=DB::table('employees')->find($v['employee_id']);Access::branch($r->user(),$e->branch_id);return DB::transaction(function()use($r,$v,$e){DB::table('business')->lockForUpdate()->first();abort_if(DB::table('payroll_runs')->where('branch_id',$e->branch_id)->where('month',substr($v['date'],0,7))->where('status','posted')->exists(),422,'Payroll already posted for this month.');$key=['employee_id'=>$e->id,'date'=>$v['date']];$before=DB::table('attendance')->where($key)->first();DB::table('attendance')->updateOrInsert($key,$v+['created_at'=>$before->created_at??now(),'updated_at'=>now()]);$id=DB::table('attendance')->where($key)->value('id');Audit::record($r->user()->id,'attendance','attendance',$id,$before,$v,'',$e->branch_id);return ['id'=>$id];});}
 public function calculate(Request $r){Access::require($r->user(),'payroll');$v=$r->validate(['branch_id'=>'required|integer|exists:branches,id','month'=>'required|date_format:Y-m','rules'=>'required|array','rules.*.name'=>'required|string|max:100','rules.*.rate'=>'required|numeric|min:0|max:100','rules.*.basis'=>'required|in:basic,gross','rules.*.type'=>'required|in:employee,employer','rules.*.cap'=>'nullable|numeric|min:0','rules.*.effective_from'=>'required|date_format:Y-m-d','rules.*.effective_to'=>'nullable|date_format:Y-m-d','adjustments'=>'nullable|array','adjustments.*.employee_id'=>'required|integer|exists:employees,id','adjustments.*.amount'=>'required|numeric','adjustments.*.deduction'=>'required|numeric|min:0','adjustments.*.advance_recovery'=>'required|numeric|min:0','adjustments.*.reason'=>'required|string|min:3|max:1000','rules_confirmed'=>'accepted']);Access::branch($r->user(),(int)$v['branch_id']);
 return DB::transaction(function()use($v,$r){DB::table('business')->lockForUpdate()->first();$old=DB::table('payroll_runs')->where('branch_id',$v['branch_id'])->where('month',$v['month'])->first();abort_if($old&&$old->status==='posted',422,'Payroll already posted.');$first=Carbon::parse($v['month'].'-01');$days=$first->daysInMonth;$last=$first->copy()->endOfMonth()->toDateString();$start=$first->toDateString();$employees=DB::table('employees')->where('branch_id',$v['branch_id'])->where('active',true)->get();abort_if($employees->isEmpty(),422,'Create employees first.');
  if($old){$id=$old->id;DB::table('payslips')->where('payroll_run_id',$id)->delete();DB::table('payroll_runs')->where('id',$id)->update(['rules'=>json_encode($v),'updated_at'=>now()]);}else $id=DB::table('payroll_runs')->insertGetId(['branch_id'=>$v['branch_id'],'month'=>$v['month'],'rules'=>json_encode($v),'created_at'=>now(),'updated_at'=>now()]);
  foreach($employees as $e){$attendance=DB::table('attendance')->where('employee_id',$e->id)->whereBetween('date',[$start,$last])->get();abort_unless($attendance->count()===$days,422,'Record every calendar day, including holidays, for '.$e->name.'.');$paid=$attendance->whereIn('status',['present','paid_leave','holiday'])->count();$basic=Amount::divide($e->monthly_paise*$paid,$days);$ot=Amount::divide($e->overtime_hour_paise*$attendance->sum('overtime_minutes'),60);$adj=collect($v['adjustments']??[])->firstWhere('employee_id',$e->id)??[];$adjust=Amount::parse($adj['amount']??0);$manual=Amount::parse($adj['deduction']??0);$advance=Amount::parse($adj['advance_recovery']??0);$gross=$basic+$ot+$adjust;$ded=$manual;$employer=0;$breakdown=[];
   foreach($v['rules']as $rule){if($rule['effective_from']>$start||(!empty($rule['effective_to'])&&$rule['effective_to']<$last))abort(422,'Rule must cover the entire payroll month; split-period statutory changes need review.');$base=$rule['basis']==='basic'?$basic:$gross;if(isset($rule['cap'])&&$rule['cap']!=='')$base=min($base,Amount::parse($rule['cap']));$amount=Amount::divide(max(0,$base)*Amount::parse($rule['rate']),10000);$breakdown[]=$rule+['amount_paise'=>$amount];if($rule['type']==='employee')$ded+=$amount;else $employer+=$amount;}
   $net=$gross-$ded-$advance;abort_if($net<0,422,'Net salary cannot be negative: '.$e->name);DB::table('payslips')->insert(['payroll_run_id'=>$id,'employee_id'=>$e->id,'basic_paise'=>$basic,'overtime_paise'=>$ot,'adjustment_paise'=>$adjust,'deductions_paise'=>$ded+$advance,'employer_paise'=>$employer,'net_paise'=>$net,'calculation'=>json_encode(['employee'=>$e,'paid_days'=>$paid,'calendar_days'=>$days,'overtime_minutes'=>$attendance->sum('overtime_minutes'),'rules'=>$breakdown,'manual_deduction'=>$manual,'advance_recovery'=>$advance,'reason'=>$adj['reason']??''])]);
  }Audit::record($r->user()->id,'payroll_calculate','payroll_runs',$id,$old,$v,'',$v['branch_id']);return ['id'=>$id];});
 }
 public function slips(Request $r,int $id){Access::require($r->user(),'payroll');$run=DB::table('payroll_runs')->find($id);abort_unless($run,404);Access::branch($r->user(),$run->branch_id);return ['run'=>$run,'slips'=>DB::table('payslips as p')->join('employees as e','e.id','=','p.employee_id')->where('payroll_run_id',$id)->select('p.*','e.name','e.code')->get()];}
 public function post(Request $r,int $id,DocumentService $svc){Access::require($r->user(),'payroll');Access::require($r->user(),'approve');return DB::transaction(function()use($r,$id,$svc){$biz=DB::table('business')->lockForUpdate()->first();$run=DB::table('payroll_runs')->lockForUpdate()->find($id);abort_unless($run,404);Access::branch($r->user(),$run->branch_id);if($run->status==='posted')return ['id'=>$run->document_id];$date=Carbon::parse($run->month.'-01')->endOfMonth()->toDateString();abort_if($biz->locked_until&&$date<=$biz->locked_until,422,'Period locked.');$slips=DB::table('payslips')->where('payroll_run_id',$id)->get();abort_if($slips->isEmpty(),422,'Calculate payroll first.');$gross=0;$net=0;$ded=0;$adv=0;$employer=0;foreach($slips as $s){$gross+=$s->basic_paise+$s->overtime_paise+$s->adjustment_paise;$net+=$s->net_paise;$ded+=$s->deductions_paise;$adv+=json_decode($s->calculation,true)['advance_recovery'];$employer+=$s->employer_paise;}$d=app(OperationsController::class)->systemDocument('payroll',$run->branch_id,$date,$r->user()->id,$gross+$employer);$svc->entry($d,'5200',$gross+$employer);$svc->entry($d,'2200',-$net);$svc->entry($d,'2210',-($ded-$adv+$employer));$svc->entry($d,'1500',-$adv);$svc->assertBalanced($d->id);DB::table('payroll_runs')->where('id',$id)->update(['status'=>'posted','document_id'=>$d->id,'updated_at'=>now()]);Audit::record($r->user()->id,'payroll_post','payroll_runs',$id,$run,['document_id'=>$d->id],'',$run->branch_id);return ['id'=>$d->id];});}
 public function print(Request $r,int $id,int $employee){$result=$this->slips($r,$id);$slip=$result['slips']->firstWhere('employee_id',$employee);abort_unless($slip,404);return view('payslip',['run'=>$result['run'],'slip'=>$slip,'calculation'=>json_decode($slip->calculation),'biz'=>DB::table('business')->first()]);}
}
